class ArchiveObj:
    """
    File-like object containing the name and binary content of the archive item.
    """
    def __init__(self, name: str, data: bytes):
        self.name = name
        self.data = io.BytesIO(data)

    def __repr__(self):
        return f"ArchiveObj(name={self.name}, data={self.data})"


