    @log_input_and_output
    def collect_mandatory_file_list(self, ru_name, documentation_path=None, additional_documentation_path=None):
        """
        Collects mandatory files list by parsing snapshot documentation. By default, snapshot documentation is being
        downloaded from remote repository. User can provide local path to custom snapshot documentation .csv file.

        :param ru_name: name of rmod for which mandatory files will be collected
        :type ru_name: str
        :param documentation_path: (Optional) full path to custom .csv snapshot documentation, e.g.
                                   /home/ute/SBTS00_ENB_9999_230609_000006_trbl_log_list.csv
        :type documentation_path: str
        :param additional_documentation_path: (Optional) full path to .csv file that extends snapshot documentation by
                                              additional mandatory files. File must have the same structure as
                                              documentation (same fieldnames and delimiter). Path example:
                                              /home/ute/custom_mandatory_files.csv
        :type additional_documentation_path: str
        """
        if f"{self._sw_version}_trbl_log_list.csv" not in os.listdir(self._snapshot_documentation_path):
            if documentation_path:
                self._copy_snapshot_documentation(documentation_path=documentation_path)
            else:
                self._download_snapshot_documentation()
                self._extract_snapshot_documentation()

        if additional_documentation_path:
            self._extend_snapshot_documentation_csv(additional_documentation_path=additional_documentation_path)
        self._get_mandatory_files_from_documentation(ru_name=ru_name)

    @log_input_and_output
    def check_if_snapshot_contains_all_mandatory_files(self, ru_name, ru_serial_number):
        """
        Checks if all mandatory files are present in snapshot.

        :param ru_name: name of rmod for which mandatory files will be checked e.g "LEFT-RMOD_L-1"
        :type ru_name: str
        :param ru_serial_number: radio serial number e.g. "CV192400997"
        :type ru_serial_number: str
        :raises NotAllMandatoryFilesPresent when any of mandatory files not present in snapshot
        """
        file_list = self._get_snapshot_file_list_from_txt()
        rmod_index = self._get_ru_index(ru_name)
        subarchives_of_archives = self._make_zip_dict(file_list=file_list, rmod_index=rmod_index)
        not_founds = self._look_for_mandatory_files(filtered_snap_file_list=subarchives_of_archives, rmod_name=ru_name, rmod_index=rmod_index,
                                                    rmod_serial_number=ru_serial_number)

        if not_founds:
            self._missing_files.append(
                {
                    "ru_name": self._rmods_info[ru_name]['name'],
                    "ru_serial_number": ru_serial_number,
                    "ru_scm_flag": self._rmods_info[ru_name]['scm_flag'],
                    "missing_files": not_founds,
                }
            )

    @log_input_and_output
    def check_if_snapshot_ru_contains_mandatory_file(self, ru_name, ru_serial_number, mandatory_file):
        """
        Checks if given mandatory file(s) are present in snapshot ru logs and returns list of file's paths.

        :param ru_name: name of rmod for which mandatory file will be checked
        :type ru_name: str
        :param ru_serial_number: radio serial number
        :type ru_serial_number: str
        :param mandatory_file: mandatory file(s), e.g. startup.zip
        :type mandatory_file: str | list(str)
        :return full path to mandatory file(s) in snapshot
        :rtype: list
        :raises NotAllMandatoryFilesPresent when any of mandatory files not present in snapshot
        """
        mandatory_file = [mandatory_file] if not isinstance(mandatory_file, list) else mandatory_file

        file_list = self._get_snapshot_file_list_from_txt()
        rmod_index = self._get_ru_index(ru_name)
        subarchives_of_archives = self._make_zip_dict(file_list=file_list, rmod_index=rmod_index)
        mandatory_file_patterns = {
            f: self._create_mandatory_file_search_pattern(f, rmod_index, ru_serial_number)
            for f in mandatory_file
        }

        matched_paths, not_founds = self._find_matched_paths(subarchives_of_archives, mandatory_file_patterns)

        if not_founds:
            self._missing_files.append(
                {
                    "ru_name": self._rmods_info[ru_name]['name'],
                    "ru_serial_number": ru_serial_number,
                    "ru_scm_flag": self._rmods_info[ru_name]['scm_flag'],
                    "missing_files": not_founds,
                }
            )

        return matched_paths

    def teardown(self):
        """
        Cleans up all tmp dirs.
        """
        self._missing_files = []
        self._remove_dir(self._snapshot_tmp_dir)

    def create_mandatory_paths(self):
        """
        Creates all mandatory paths.
        """
        for path in (
            self._snapshot_documentation_path,
            self._snapshot_tmp_dir,
            self._snapshot_tmp_extract_dir,
        ):
            os.mkdir(path)

    def verify_test_execution(self):
        """
        Verifies that coverage iteration has finished without any missing files in snapshot.

        :raises: NotAllMandatoryFilesPresent when _missing_files list is not empty
        """
        if self._missing_files:
            missing_msg = self._create_missing_files_err_msg()
            raise NotAllMandatoryFilesPresent(f"Snapshot coverage: {self._coverage}, missing mandatory files for the following RMODs:\n"
                                              + '\n'.join(missing_msg))

    def disconnect(self):
        self._admin.teardown_admin(connection=self._default_admin_snap_alias)

    @log_input_and_output
    def find_and_copy_journals_from_3rd_depth_snapshot(self, snapshot_dir_path):
        """
        Extracts recursively snapshot from "snapshot_dir_path".
        Finds every journal.txt file in third depth of snapshot then copies located journals
        to "snapshot_dir_path"/snapshot_journal/.
        Returns path to directory of copied journals.
        Raises an exception when there is no journal.txt file in third depth of snapshot.

        :param snapshot_dir_path: path to zipped snapshot
        :type snapshot_dir_path: str
        :return: path to directory of copied journals
        :rtype: str
        """
        journal_path = self._create_directory_for_journal_files(snapshot_dir_path)
        self._extract_all_zips_from_directory_recursively(snapshot_dir_path)
        unpacked_snapshot_dir_path = snapshot_dir_path + '/snapshot_zip/'

        log_iterator = 1

        for snapshot_file_layer_1 in os.listdir(unpacked_snapshot_dir_path):
            if os.path.isdir(join(unpacked_snapshot_dir_path, snapshot_file_layer_1)):
                for snapshot_file_layer_2 in os.listdir(unpacked_snapshot_dir_path + snapshot_file_layer_1):
                    journal_location = f'{unpacked_snapshot_dir_path}{snapshot_file_layer_1}/' \
                        f'{snapshot_file_layer_2}/journal.txt'
                    if os.path.isfile(journal_location):
                        log_result('copying file: ' + journal_location)
                        shutil.copy2(journal_location, f"{journal_path}journal{log_iterator}.LOG")
                        log_iterator += 1

        self._remove_dir(unpacked_snapshot_dir_path)

        if log_iterator == 1:
            raise JournalFilesNotFoundInThirdDepthOfSnapshot(
                "Could not find journal.txt files in third depth of snapshot."
            )

        return journal_path

    @log_input_and_output
    def get_list_of_snapshot_components_from_snapshot_file_list(self):
        """
        Gets list of snapshot components based on snapshot_file_list.txt file.
        If component is archive file then dictionary with name of archive as key and list of
        archived files as value is treated as element of created components list.

        :return: list of snapshot components, e.g. :
                    [{'BTS_L1231000889_RMOD_L_1_ccs-rt-runtime.tar.gz': []},
                     {"BTS_part8.zip": ["BTS_L1231000889_RMOD_L_1_1111_draco-reg_dumps.log.gz",
                                        "BTS_L1231000889_RMOD_L_1_frozenFrameDraco.log.pm2.gz",
                                        "BTS_L1231000889_RMOD_L_1_frozenFrameDraco.log.pm1.gz",
                                        "BTS_L1231000889_RMOD_L_1_frozenFrameDraco.log.gz"]},
                     "snapshotHistory.txt",
                     {"pm.zip": ["pmCounterMap.json",
                                 "pmCounterTranslation.json"]},
                     "BTS_27034368_metadata.txt"]
        :rtype: list
        :raises: SnapshotFileListError when format of snapshot file list is not correct.
        """
        components_list = []
        archived_files = {}
        current_archive_name = None

        file_list = self._get_snapshot_file_list_from_txt()

        for file in file_list:
            if file:
                if not self._is_subfile_in_snapshot_file_list(file):
                    if current_archive_name in archived_files:
                        components_list.append(archived_files)
                        archived_files = {}
                    if not self._is_archive_in_snapshot_file_list(file):
                        components_list.append(file)
                        continue
                    else:
                        current_archive_name = file.rstrip(":")
                        archived_files[current_archive_name] = []
                        continue
                else:
                    if current_archive_name is None:
                        raise SnapshotFileListError("File list is not correct, subfile name cannot be before file name")
                    archived_files[current_archive_name].append(file.lstrip())
        if archived_files:
            components_list.append(archived_files)

        return components_list

    @log_input_and_output
    def find_file_in_snapshot_file_list(self, filename, raise_exception=True):
        """
        Gets snapshot internal path to particular filename, based on snapshot_file_list.txt file.
        If file with particular filename is located inside some archive file, then returns path with archive name and
        filename, e.g.: "pm.zip/pmCounterMap.json"
        If file with particular filename ins not archived, then only returns filename, e.g.: "snapshotHistory.txt"
        If file with filename is not defined in snapshot_file_list.txt file, then returns False.

        :param filename: name of file to be found in snapshot file list, e.g.:
                           'BTS_1M222011926_RMOD_L_1_gandalf_logs.tar.gz'
                         or filename regex pattern for fullmatch usage, e.g.:
                           'BTS_1M222011926_RMOD_L_1_.*.tar.gz'
        :type filename: str
        :param raise_exception: True if FileNotFoundInSnapshot exception should be raised when filename not found in
                            snapshot file list, False if FileNotFoundInSnapshot exception should not be raised, then
                            False will be returned when filename not found in snapshot file list. Defaults to True.
        :type raise_exception: bool
        :return: internal snapshot path to file with provided filename, e.g.:
                'BTS_part9.zip/BTS_1M222011926_RMOD_L_1_gandalf_logs.tar.gz'
                or False if filename cannot be found in snapshot file list and raise_exception is set to False.
        :rtype: str or bool
        :raises: FileNotFoundInSnapshot when provided filename cannot be found in snapshot file list.
        """
        file_list = self.get_list_of_snapshot_components_from_snapshot_file_list()

        for file in file_list:
            if isinstance(file, dict):
                archive_name = [name for name in file.keys()][0]
                if re.fullmatch(filename, archive_name):
                    return archive_name
                else:
                    for subfile in list(file.values())[0]:
                        if re.fullmatch(filename, subfile):
                            return f"{list(file.keys())[0]}/{subfile}"
            else:
                if re.fullmatch(filename, file):
                    return filename
        if raise_exception:
            raise FileNotFoundInSnapshot(f"File {filename} cannot be found in snapshot file list.")
        else:
            log_warning(f"File {filename} cannot be found in snapshot file list.")
            return False

    @log_input_and_output
    def extract_shapshot_file_based_on_internal_path(self, internal_snapshot_path, raise_exception=True):
        """
        Extracts snapshot archive based on provided internal shanpshot path to file or directory into
        default localization snapshot_tmp_extract_dir defined in setup_snapshot_settings. Provided internal path can
        contain other zip or tar archives.
        If the last of internal_snapshot_path is file then only specific file will be extracted.
        If the last of internal_snapshot_path is archive or directory then all files from archive or directory will be
        extracted.

        :param internal_snapshot_path: relative internal snapshot path to file or dictionary to extract, example:
                            BTS_part2.zip/BTS_L1231000889_RMOD_L_1_2011_l1low_iq_capture_thor.tar.gz/
                            or
                            BTS_part3.zip/BTS_1M222011926_RMOD_L_1_gandalf_logs.tar.gz/gandalf_logs/l1low_logs_made_es2/
                            or
                            BTS_part2.zipBTS_L1231000889_RMOD_L_1_2011_l1low_iq_capture_thor.tar.gz/BTS_L1231000889_
                            RMOD_L_1_2011_l1low_iq__get_internal_file_list_to_extractcapture_thor.tar/l1low_iq_capture_0_fh0_ul_2023-12-22T12-01-44Z.bin
        :type internal_snapshot_path: str
        :param raise_exception: True if ArchiveExtractionError exception should be raised when archive extraction
                            could not be done, False if ArchiveExtractionError exception should not be raised, then
                            False will be returned when archive extraction could not be done. Defaults to True.
        :type raise_exception: bool
        :return: absolute path to directory with extracted files or False if archive extraction has failed and
                            raise_exception is set to False.
        :rtype: str or bool

        :raises: ArchiveExtractionError when archive extraction has failed and  raise_exception is set on True.
        """
        if not os.path.exists(self._snapshot_tmp_extract_dir):
            os.makedirs(self._snapshot_tmp_extract_dir)
        shutil.copy(os.path.join(self._snapshot_dir, self._snapshot_file_name), self._snapshot_tmp_extract_dir)

        internal_files_to_extract = self._get_internal_file_list_to_extract(internal_snapshot_path)
        list_of_files_to_extract = [self._snapshot_file_name] + internal_files_to_extract

        for idx, file_object in enumerate(list_of_files_to_extract):

            if idx == len(list_of_files_to_extract) - 1:
                if ".zip" in file_object or ".tar" in file_object:
                    list_of_files_to_extract.append("unpack_all_files")
                else:
                    break

            next_object = list_of_files_to_extract[idx + 1]
            try:
                unpack_success = self._unpack_archive(path=self._snapshot_tmp_extract_dir,
                                                      item=file_object,
                                                      extract_dir_path=self._snapshot_tmp_extract_dir,
                                                      member=next_object if "." in next_object else None)
            except KeyError:
                unpack_success = False

            if not unpack_success:
                if raise_exception:
                    raise ArchiveExtractionError(f"Cannot unpack snapshot element: {file_object}. Probably element "
                                                 f"does not exist in snapshot file.")
                else:
                    log_warning(f"Cannot unpack snapshot element: {file_object}. Probably element does not exist in "
                                f"snapshot file.")
                    return False

            if "/" in next_object:
                if "." in next_object:
                    shutil.copy(os.path.join(self._snapshot_tmp_extract_dir, next_object),
                                self._snapshot_tmp_extract_dir)
                    list_of_files_to_extract[idx + 1] = next_object.split("/")[-1]
                else:
                    files_paths = [os.path.join(self._snapshot_tmp_extract_dir, next_object, f)
                                   for f in os.listdir(os.path.join(self._snapshot_tmp_extract_dir,
                                                                    next_object))
                                   if
                                   os.path.isfile(os.path.join(self._snapshot_tmp_extract_dir,
                                                               next_object, f))]
                    for file_path in files_paths:
                        shutil.copy(file_path, self._snapshot_tmp_extract_dir)

        return self._snapshot_tmp_extract_dir

    @staticmethod
    @log_input_and_output
    def find_and_copy_l1low_iq_capture_bin_file(file_dir_path, destination_dir_path):
        """
        Finds l1low IQ capture file with bin extension and copies file to specified path.

        :param file_dir_path: path of directory with l1low IQ capture file (bin extension)
        :type file_dir_path: str
        :param destination_dir_path: path of destination directory copy l1low IQ capture file (bin extension)
        :type destination_dir_path: str
        :return: full path to copied l1low IQ capture file, e.g.:
                "/home/ute/my_dir/l1low_iq_capture_0_fh0_ul_2024-01-13T11-18-43Z.bin"
        :rtype: str
        :raises: FileNotFoundInSnapshot when l1low IQ capture file not found.
        """
        for root, dirs, files in os.walk(file_dir_path):
            for file in files:
                if ".bin" in file:
                    shutil.copy(os.path.join(file_dir_path, file), os.path.join(destination_dir_path, file))
                    return os.path.join(destination_dir_path, file)
        raise FileNotFoundInSnapshot("L1 IQ Data file with bin extension is not found in snapshot file")

    @staticmethod
    @log_input_and_output
    def get_active_faults_list_from_rmod_fault_history_log_file(file_path):
        """
        Gets list of faults with all included information from RMOD fault history log file, visible under active faults
        section.

        :param file_path: full path to rmod fault history log file, including filename and txt extension.
        :type file_path: str
        :return: list of faults from fault events section, e.g.:
                ['<2024-01-19T08:58:38.845000Z> \tEFaultId_PostDdrTestFailed (1416)  \t  module  \twarning  \t1',
                 '<2024-01-19T09:58:38.845000Z> \tSome_other_fault (0000)  \t  module  \twarning  \2']
        :rtype: list
        """
        with open(file_path, "r") as f:
            file = f.read()
        active_faults = file.split(" InActive faults:")[0].split(" Active faults:")[-1]
        result = re.split(r"=*=", active_faults)[-1]

        return [fault for fault in result.split("\n") if fault]

    @staticmethod
    @log_input_and_output
    def get_fault_events_list_from_rmod_fault_history_log_file(file_path):
        """
        Gets list of faults with all included information from RMOD fault history log file, visible under fault events
        section.

        :param file_path: full path to rmod fault history log file, including filename and txt.gz extension.
        :type file_path: str
        :return: list of faults from fault events section, e.g.:
                ['<2024-01-19T08:58:38.845000Z> \tEFaultId_PostDdrTestFailed (1416)  \t  module  \twarning  \t1',
                 '<2024-01-19T09:58:38.845000Z> \tSome_other_fault (0000)  \t  module  \twarning  \2']
        :rtype: list
        """
        txt_path = ".".join(file_path.split(".")[:-1])
        with gzip.open(file_path, 'rb') as file_gz:
            with open(txt_path, 'wb') as file_txt:
                shutil.copyfileobj(file_gz, file_txt)

        with open(txt_path, "r") as f:
            file = f.read()
        fault_events = file.split(" Fault events:")[-1]
        result = re.split(r"=*=", fault_events)[-2]

        return [fault for fault in result.split("\n") if re.search(r"\d{4}-\d{2}-\d{2}", fault)]

    @staticmethod
    @log_input_and_output
    def check_if_fault_2920_and_fault_2919_exist_in_fault_history_log(file_path):
        """
        Checks if fault 2920 and 2919 are available in RMOD fault history log file (in fault event section).

        :param file_path: full path to rmod fault history log file, including filename and txt extension.
        :type file_path: str
        :raises: AssertionError when fault 2920 or 2919 not found in fault history log file.
        """
        fault_events_list = Snapshot.get_fault_events_list_from_rmod_fault_history_log_file(file_path)
        high_count, low_count = 0, 0
        for fault in fault_events_list:
            if "EfaultId_DcInputVoltageTooLow" in fault:
                low_count += 1
            if "EfaultId_DcInputVoltageTooHigh" in fault:
                high_count += 1

        if high_count == 0 or low_count == 0:
            raise AssertionError(f"Info about Fault 2920 or 2919 not found in fault history log file: {file_path}")

    @staticmethod
    @log_input_and_output
    def check_if_active_fault_1416_in_fault_history_log_file(file_path):
        """
        Checks if fault 1416 is available under active faults section in RMOD fault history log file.

        :param file_path: full path to rmod fault history log file, including filename and txt extension.
        :type file_path: str
        :return: True is active fault 1416 is available in provided faults list, False otherwise.
        :rtype: bool
        """
        active_faults_list = Snapshot.get_active_faults_list_from_rmod_fault_history_log_file(file_path)
        for fault in active_faults_list:
            if "EFaultId_PostDdrTestFailed (1416)" in fault:
                return True
        return False

    @staticmethod
    @log_input_and_output
    def _get_list_of_autonomous_snapshots(mrbts_id, dir_path='/home/ute'):

        return [f for f in os.listdir(dir_path) if os.path.isdir(os.path.join(dir_path, f))
                and re.fullmatch(rf"Snapshot_MRBTS-{mrbts_id}_.*", f)]

    @log_input_and_output
    def _wait_for_autonomous_snapshot_initialization(self, mrbts_id, dir_path, timeout):
        self._last_autonomous_snapshot_name = "waiting"
        self._waiting_time_for_autonomous_reset = timeout

        try:
            initial_snapshot_list = self._get_list_of_autonomous_snapshots(mrbts_id, dir_path)

            start_time = time.time()
            while True:
                current_snapshot_list = self._get_list_of_autonomous_snapshots(mrbts_id, dir_path)
                new_snapshot = set(current_snapshot_list) - set(initial_snapshot_list)
                new_snapshot = list(new_snapshot)

                if len(new_snapshot) == 1:
                    self._last_autonomous_snapshot_name = new_snapshot[0]
                    break
                elif len(new_snapshot) > 1:
                    raise SnapshotCollectionError(f"Found more than one snapshot file: {new_snapshot}")

                if time.time() - start_time >= timeout:
                    self._last_autonomous_snapshot_name = None
                    break

                time.sleep(1)
        finally:
            if self._last_autonomous_snapshot_name == "waiting":
                self._last_autonomous_snapshot_name = None

    def _get_directory_size(self, dir_path):
        prepend = partial(os.path.join, dir_path)
        return sum([(os.path.getsize(f) if os.path.isfile(f) else self._get_directory_size(f))
                    for f in map(prepend, os.listdir(dir_path))])

    @staticmethod
    @log_input_and_output
    def _is_subfile_in_snapshot_file_list(filename):
        return True if re.match(r'\s', filename) else False

    @staticmethod
    @log_input_and_output
    def _is_archive_in_snapshot_file_list(filename):
        return any(ext in filename for ext in [".zip", ".tar"])

    @staticmethod
    @log_input_and_output
    def _get_internal_file_list_to_extract(file_path_to_extract):
        list_of_file_to_extract = []
        tmp_file_path = ""

        for file in file_path_to_extract.split("/"):
            if "." in file:
                if tmp_file_path:
                    list_of_file_to_extract.append(tmp_file_path + "/" + file)
                else:
                    list_of_file_to_extract.append(file)
                tmp_file_path = ""
            else:
                tmp_file_path = file if tmp_file_path == "" else tmp_file_path + "/" + file
        if tmp_file_path:
            list_of_file_to_extract.append(tmp_file_path)
        return list_of_file_to_extract

    @log_input_and_output
    def _create_directory_for_journal_files(self, snapshot_dir_path):
        """
        Prepares and creates directory for journal.txt files found in third depth of snapshot.
        Returns path to directory for journal files.

        :param snapshot_dir_path: path to snapshot
        :type snapshot_dir_path: str
        :return: path to directory for copied journals
        :rtype: str
        """
        journal_path = snapshot_dir_path + '/snapshot_journal/'
        os.mkdir(journal_path)

        return journal_path

    def _extract_all_zips_from_directory_recursively(self, path):
        """
        Extracts recursively all archives from path provided. Extracted archive is being removed after extract.
        All archives names met will be returned

        :param path: path to directory which contains zips to unpack
        :type path: str
        :return: list of file names met or list of tuple with zipped file name and its size
        :rtype: list of str OR list of tuple(str, int)
        """
        archives_met, dirs_met, files_met = [], [], []

        dir_list = os.listdir(path)
        while True:
            for item in dir_list:

                if item not in archives_met and self._unpack_archive(path, item, join(path, item.replace('.', '_'))):
                    archives_met.append(item)
                    os.remove(join(path, item))

                elif os.path.isdir(join(path, item)) and item not in dirs_met:
                    archives_met.extend(
                        self._extract_all_zips_from_directory_recursively(path=join(path, item))
                    )
                    dirs_met.append(item)

                else:
                    files_met.append(item)

            if (not self._check_if_archive_visible_in_path(path) and not self._check_if_dir_visible_in_path(path)
                    or self._check_if_already_visited(path, archives_met, dirs_met, files_met)):
                break

            dir_list = os.listdir(path)

        return archives_met

    @staticmethod
    def _check_if_already_visited(path, archives_met, dirs_met, files_met):
        """
        Checks if everything under given path was already searched. If new directory has appeared due to previously
        unpacked archive it will be ignored.
        :param path: path to be checked
        :type path: str
        :param archives_met: list of archives that are already in seen archives
        :type archives_met: list of str
        :param dirs_met: list of dirs that are already in seen dirs
        :type dirs_met: list of str
        :param files_met: list of files that are already in seen files
        :type files_met:list of str
        :return: boolean if everything in path was already searched
        :rtype: bool
        """
        items_should_be_found, items_found = os.listdir(path), []

        if items_should_be_found:

            for item in items_should_be_found:
                if item in archives_met + dirs_met + files_met:
                    items_found.append(item)
            return sorted(items_should_be_found) == sorted(items_found)

        return False

    @staticmethod
    def _check_if_archive_visible_in_path(path):
        archive_patterns = [".*\\.zip$", ".*\\.tar.gz$", ".*\\.tar$", ".*\\.tgz$", ".*\\.txz$", ".*\\.xz$", ".*\\.gz$"]

        return any(
            map(
                lambda x: any([re.match(pattern, x) for pattern in archive_patterns]),
                os.listdir(path),
            )
        )

    @staticmethod
    def _check_if_dir_visible_in_path(path):
        return any([os.path.isdir(join(path, item)) for item in os.listdir(path)])

    @log_input_and_output
    def _look_for_mandatory_files(self, filtered_snap_file_list: dict, rmod_name: str, rmod_index: str, rmod_serial_number: str) -> list[str]:
        """
        Searches the snapshot for mandatory file containers and files, and verifies that they are present.
        Search flow:
        - find for file container snapshot parent archive in snapshot_file_list.txt
        - search for mandatory file container in parent archive
        - search for mandatory files in mandatory file container archive

        :param filtered_snap_file_list: filtered and parsed to dictionary snapshot_file_list.txt
        :type filtered_snap_file_list: dict
        :param rmod_name: name of the RMOD, e.g. "LEFT-RMOD_L-1"
        :type rmod_name: str
        :param rmod_index: parsed rmod_name e.g. "1"
        :type rmod_index: str
        :param rmod_serial_number: serial number of the RMOD, e.g. "6Q183230441"
        :type rmod_serial_number: str
        :return: list of mandatory files that have not been found in snapshot files
        :rtype: list[str]
        """
        not_founds = []
        log_step(f"Looking for mandatory files for RMOD id: {rmod_index}, sn: {rmod_serial_number}, "
                 f"scm_flag: {self._rmods_info[rmod_name]['scm_flag']}\nin snapshot: {self._snapshot_path}")

        for file_container, filenames in self._mandatory_items.items():
            container_search_pattern = self._create_file_container_search_pattern(file_container, rmod_index, rmod_serial_number)
            parent_container_archive = self._find_parent_archive(filtered_snap_file_list, container_search_pattern)
            if not parent_container_archive:
                not_founds.append(
                    f"- file container '{file_container}' not found in any archive in snapshot_file_list.txt\n"
                    f"  mandatory files in file container: {filenames}"
                )
                continue

            container_archive = self._find_container_in_archive(parent_container_archive, container_search_pattern)
            if not container_archive:
                not_founds.append(
                    f"- file container '{file_container}' not found in snapshot, couldn't find archive '{parent_container_archive.filename}'\n"
                    f"  mandatory files in file container: '{filenames}'"
                )
                continue

            log_result(f"mandatory file container: '{file_container}' matched with '{parent_container_archive.filename}/{container_archive.name}'")
            missing_mandatory_files = self._find_missing_files_in_container(container_archive, filenames, rmod_index, rmod_serial_number,
                                                                            parent_container_archive.filename)
            if missing_mandatory_files:
                not_founds.append(
                    f"- missing files '{missing_mandatory_files}' in file container '{file_container}', "
                    f"files searched in '{parent_container_archive.filename}/{container_archive.name}"
                )

        return not_founds

    @staticmethod
    def _remove_dir(dir_path):
        """
        Removes entire directory tree (all files and subdirectories below it).

        :param dir_path: tree directory that is going to be deleted
        :type dir_path: str
        """
        shutil.rmtree(dir_path, True)

    @log_input_and_output
    def _get_list_of_all_files_from_dir(self, dir_path):
        """
        Return list of all files in dir_name and their subdirectories

        :param dir_path: directory name
        :type dir_path: str
        :return: Return list of files met
        :rtype list of str
        """
        list_of_files = os.listdir(dir_path)
        all_files = []
        for entry in list_of_files:
            full_path = join(dir_path, entry)

            if os.path.isdir(full_path):
                all_files = all_files + self._get_list_of_all_files_from_dir(full_path)
            else:
                all_files.append(full_path)
        return all_files

    @log_input_and_output
    def _make_zip_dict(self, file_list, rmod_index):
        """
        Creates dictionary based on snapshot_file_list.txt and ru number.
        Keys are names of archives and values are names of their subarchives

        :param file_list: list of files from snapshot_file_list.txt
        :type file_list: list
        :param rmod_index: ru number
        :type rmod_index: int or str
        :return: dictionary of zip name and it's content e.g.
            {
                "BTS_part1.zip": [
                    "BTS_6Q183230441_RMOD_L_1_auth.zip",
                    "BTS_6Q183230441_RMOD_L_1_dmesg.zip",
                ]
                "BTS_part2.zip": [
                    "not_RMOD_logs.zip",
                ]
            }
        :rtype: dict
        """
        zip_dict = {
            file_name.rstrip(): self._get_zip_content(file_name.rstrip(), file_list)
            for file_name in file_list
            if "   " not in file_name[:3]
        }

        return {
            file_name.rstrip(": "): zip_content
            for file_name, zip_content in zip_dict.items()
            if self._check_if_contains_rmod_logs(zip_content + [file_name], rmod_index)
        }

    @staticmethod
    def _check_if_contains_rmod_logs(list_of_content, rmod_index):
        """
        Checks if serial number of rmod which is checked is present in logs file names.

        :param list_of_content: list of content to be checked
        :type list_of_content: list
        :param rmod_index: ru number
        :type rmod_index: int or str
        :return: True if any file from list contains rmod prefix
        :rtype: bool
        """
        return any(
            ["RMOD_L_{}".format(rmod_index) in str(elem) for elem in list_of_content]
        )

    @staticmethod
    def _get_zip_content(_file_name, lines_of_snapshot_content):
        """
        Parses snapshot content file. Finds name under _file_name provided and gets
        all of the sub file names.

        :param _file_name: file name for which content will be parsed
        :type _file_name
        :param lines_of_snapshot_content: lines of snapshot content file to be searched
        :type lines_of_snapshot_content: list of str
        :return: list of sub file names of _file_name provided
        :rtype: list of str
        """
        content = []
        start = False
        for file_name in lines_of_snapshot_content:

            if start:
                if "   " in file_name[:3]:
                    content.append(file_name.rstrip()[3:])
                else:
                    return content
            if file_name == _file_name:
                start = True
        return content

    def _get_snapshot_file_list_from_txt(self):
        """
        Gets list of snapshot content from snapshot_file_list.txt file in snapshot.

        :return: list of snapshot files according to txt file
        :rtype: list of str
        """
        with ZipFile(self._snapshot_path, "r") as zfile:
            for name in zfile.namelist():
                if "snapshot_file_list.txt" in name:
                    return [
                        f.rstrip().decode()
                        for f in zfile.open("snapshot_file_list.txt") if f.rstrip().decode()
                    ]

        raise NoMandatoryItems("snapshot_file_list.txt could not be found in snapshot.")

    @log_input_and_output
    def _get_mandatory_files_from_documentation(self, ru_name):
        """
        Gets a filtered list of all mandatory files from the CSV file for the current sw version.

        :param ru_name: rmod name for which mandatory files should be returned
        :type ru_name: str
        :return: list of mandatory files for ru_name provided
        :rtype: list of str
        """

        csv_file_name = f"{self._sw_version.split('T1')[0]}_trbl_log_list.csv"
        csv_file_path = join(self._snapshot_documentation_path, csv_file_name)

        with open(csv_file_path, "r") as f:
            reader = csv.DictReader(f, delimiter=";")
            csv_list = list(reader)
            parsed_documentation = self._parse_documentation(csv_list=csv_list, ru_name=ru_name)
            self._mandatory_items = self._filter_mandatory_items(ru_name=ru_name, mandatory_containers_with_files=parsed_documentation)

    def _parse_documentation(self, csv_list, ru_name):
        """
        Parses records in csv_list for ru_name provided.

        :param csv_list: list of documentation records
        :type csv_list: list of csv records
        :param ru_name: rmod name
        :type ru_name: str
        """
        mandatory_containers_with_files = OrderedDict()
        rmod_scm_flag = self._rmods_info[ru_name]['scm_flag'].replace("_", "-")
        log_step(f'Parsing documentation for RMOD: {self._rmods_info[ru_name]}')

        for item in csv_list:
            if (
                    item['deployable unit'] == 'RF_MODULE'
                    and item['mandatory flag'] == '1'
                    and re.search(rf"\b{re.escape(rmod_scm_flag)}\b", item['SCM assembly info'])
            ):
                if self._coverage == 'Full' or (self._coverage == 'Minor' and item['coverage'] == 'M'):
                    container, filename = item.get("file container", ""), item.get("filename")
                    if container == "":
                        container = "None"
                    mandatory_containers_with_files.setdefault(container, []).append(filename)

        if not mandatory_containers_with_files:
            raise NoMandatoryItems(f"No mandatory items found in documentation for RU: {ru_name}.")

        return mandatory_containers_with_files

    def _filter_mandatory_items(self, ru_name, mandatory_containers_with_files):
        """
        Filters mandatory items (file containers and filenames).

        :return: Dictionary of mandatory file containers and their mandatory files for ru_name is provided.
        :rtype: dict
        """
        mandatory_containers_with_files = {
            self._applay_filters(items=key, ru_name=ru_name, item_type='container'): self._applay_filters(items=values, ru_name=ru_name)
            for key, values in mandatory_containers_with_files.items()
        }

        log_result("Mandatory_containers_with_files:\n"
                   + "".join(f"{i}: {k}: {v}\n" for i, (k, v) in enumerate(mandatory_containers_with_files.items(), 1)))

        return mandatory_containers_with_files

    @log_input_and_output
    def _filter_files_by_rmod_program(self, ru_name, data_to_be_filtered):
        rmod_scm_flag = self._rmods_info[ru_name]["scm_flag"]

        rmod_hw_family_program_list = rmods_programs.get(rmod_scm_flag, {})
        rmod_program = rmod_hw_family_program_list.get(self._rmods_info[ru_name]["productCode"].split(".")[0], None)

        excluded_programs = None
        if rmod_program:
            excluded_programs = set(programs_file_suffixes[rmod_scm_flag].values())
            excluded_programs.remove(programs_file_suffixes[rmod_scm_flag][rmod_program])
        exclude_pattern = f"^((?!{'|'.join(excluded_programs)}).)*$" if excluded_programs else ".*"

        return [
            record for record in data_to_be_filtered
            if re.search(fr"{exclude_pattern}", record)
        ]

    @staticmethod
    def _get_ru_index(ru_name):
        """
        Gets rmod index for ru_name provided.

        :param ru_name: rmod name
        :type ru_name: str
        :return: rmod index
        :rtype: str
        :raises RUIndexParseError when could not parse rmod id from ru_name
        """
        for elem in ru_name.split("-"):
            if elem.isdigit():
                log_env_state("RU index: {}".format(elem))
                return elem
        raise RUIndexParseError("Could not find ru number.")

    def _download_snapshot_documentation(self):
        """
        Downloads snapshot documentation according to current sw version.
        """
        snapshot_doc_url = self._get_snapshot_documentation_url()
        documentation_path = join(self._snapshot_documentation_path, "snapshot_doc.tgz")
        request = Request(snapshot_doc_url)
        request.add_header("X-JFrog-Art-Api", self._artifactory_token)
        url = urlopen(request)

        try:
            with open(documentation_path, "wb") as snap_documentation_file:
                snap_documentation_file.write(url.read())
                log_result(
                    "Downloading has been performed "
                    "without any problems from {}".format(snapshot_doc_url)
                )
        except HTTPError as e:
            log_suppression("HTTP Error: {}; {}".format(e.code, url))
        except URLError as e:
            log_suppression("URL Error: {}; {}".format(e.reason, url))

    def _extract_snapshot_documentation(self):
        """
        Extracts downloaded snapshot documentation in snapshot_documentation directory.
        """
        tf = TarFile.open(join(self._snapshot_documentation_path, "snapshot_doc.tgz"))
        tf.extractall(join(self._snapshot_documentation_path))
        log_result(
            "Extracted {} to {}".format(
                join(self._snapshot_documentation_path, "snapshot_doc.tgz"),
                join(self._snapshot_documentation_path),
            )
        )

    def _get_snapshot_documentation_url(self):
        """
        Gets snapshot documentation url.
        :return: snapshot documentation url
        :rtype: str
        """
        if self._verify_if_sw_version_is_knife(self._sw_version):
            return f"https://es-si-s3-z2.eecloud.nsn-net.net/knife-results/{self._sw_version.split('_')[-1]}/" \
                   f"{self._sw_version}_snapshot_documentation.tgz"

        return f"https://artifactory-espoo2.int.net.nokia.com/artifactory/" \
               f"mn-cosi-sran-central-public-local/build/{self._sw_version.split('_')[0]}/{self._sw_version}/" \
               f"{self._sw_version}_snapshot_documentation.tgz"

    def _copy_snapshot_documentation(self, documentation_path):
        """
        Copies and renames provided csv snapshot documentation in snapshot_documentation directory.
        :param documentation_path: full path to .csv snapshot documentation
        :type documentation_path: str
        """
        shutil.copy(documentation_path, join(self._snapshot_documentation_path,
                                             "{}_trbl_log_list.csv".format(self._sw_version.split("T1")[0])))
        log_result(
            "Copied {} to {}".format(documentation_path, join(self._snapshot_documentation_path))
        )

    @property
    def _rmods_info(self):
        """
        Gets rmods info with defined SCM flags for all rmods, e.g. :
        {
            "RIGHT-RMOD_L-1": {
                "name": "AEQA",
                "serialNumber": "1234567",
                "build": "RFSW.001.011",
                "productCode": "475432A.101",
                "distName": "/MRBTS-1/RAT-1/RUNTIME_VIEW/MRBTS_R-1/EQM_R-1/APRQM_R-1/RMOD_R-1",
                "scm_flag": "srm6",
            }
        }

        :return: rmods info
        :rtype: dict
        :raise WFTError when details for given radio software have not been found.
        """
        if not self._rmods_info_cache:
            rmod_details_with_rfsw = self._get_rmods_details()

            for rmod_name, rmod_details in rmod_details_with_rfsw.items():
                rmod_build_split = rmod_details["build"].split(".")
                rmod_details_with_rfsw[rmod_name]["scm_flag"] = WFT().get_scm_flag(
                    ".".join([*rmod_build_split[:-1], rmod_build_split[-1].split("TP")[0]])
                )
            self._rmods_info_cache = rmod_details_with_rfsw

        return self._rmods_info_cache

    @log_input_and_output
    def _get_rmods_details(self):
        data = self._get_rmods_data_from_infomodel()

        rmods_dist_name = [
            dist_name
            for dist_name in data.keys()
            if ("BTS_L-1" in dist_name or "BTS_L-4" in dist_name)
            and "RMOD_L-" in dist_name.split("/")[-1]
        ]

        builds = {
            dist_name: value
            for dist_name, value in data.items()
            if "BUILD_DATA_L" in dist_name.split("/")[-1]
        }

        rmods_info = {}
        for build, build_info in builds.items():
            for rmod_dist_name in rmods_dist_name:
                if rmod_dist_name in build and ("BTS_L-1" in build or "BTS_L-4" in build):
                    side = "LEFT-" if "BTS_L-1" in build else "RIGHT-"
                    rmods_info[side + rmod_dist_name.split("/")[-1]] = {
                        "name": data[rmod_dist_name]["productName"],
                        "serialNumber": data[rmod_dist_name]["serialNumber"],
                        "productCode": data[rmod_dist_name]["productCode"],
                        "build": build_info.get("bldName"),
                        "distName": rmod_dist_name,
                    }

        return rmods_info

    @staticmethod
    def _get_rmods_data_from_infomodel():
        info = ute_admin_infomodel()
        info.setup_infomodel(
            address=BuiltIn().get_variable_value(
                "${tl.gnbs[0].cu.oam_http_connection_details.addr}"
            ),
            port=BuiltIn().get_variable_value(
                "${tl.gnbs[0].cu.oam_http_connection_details.port}"
            ),
        )
        info.connect_infomodel()

        try:
            return info.get_infomodel_dump(dist_name_regex="RMOD_[L,R]-")
        finally:
            info.teardown_all_aliases_for_infomodel()

    def _validate_sw_version(self, sw_version):
        """
        Validates correctness of software version name

        :param sw_version: Software version read from API
        :type sw_version: str
        :return: sw_version if validated correctly.
        :rtype: str
        :raises SwStreamNotSupported when sw_version provided does not match any of sw patterns
        """
        if re.match(self._sbts_sw_pattern, sw_version) or self._verify_if_sw_version_is_knife(sw_version):
            return sw_version
        raise SwStreamNotSupported("'{}' does not match SW patterns".format(sw_version))

    def _unpack_archive(self, path, item, extract_dir_path, member=None):
        """
        Unpacks following archive formats: .zip, .gz, .xz, ,tar, .tar.gz, .tgz, .txz
        To extract all object from archive file, member parameter should be None (default).
        To extract only specific object (file or directory) please define member as internal path to particular object.

        :param path: absolute path to directory with archive file to unpack.
        :type path: str
        :param item: file name of archive to unpack, containing archive extension.
        :type item: str
        :param extract_dir_path: absolute path to directory to unpack archive content
        :type extract_dir_path: str
        :param member: internal archive path to object or directory witch will be unpacked. Default None means all
                       objects from archive will be unpacked.
        :type member: str or None
        :return: True when archive unpack has finished successfully, False otherwise
        :rtype: bool
        :raises BadZipfile, TarError, OSError, LZMAError or EOFError when archive unpack has failed, example when
                archive is corrupted
        """
        zip_pattern = ".*\\.zip$"
        gzip_pattern = ".*\\.gz$"
        xz_pattern = ".*\\.xz$"
        tar_patterns = [".*\\.tar.gz$", ".*\\.tar$", ".*\\.tgz$", ".*\\.txz$"]

        try:

            if re.match(zip_pattern, item):
                with ZipFile(join(path, item)) as zip_file:
                    if member is None:
                        zip_file.extractall(path=extract_dir_path)
                    else:
                        zip_file.extract(member=member, path=extract_dir_path)
                return True

            elif any([re.match(tar_pattern, item) for tar_pattern in tar_patterns]):
                with TarFile.open(join(path, item)) as tar_file:
                    if member is None:
                        tar_file.extractall(path=extract_dir_path)
                    else:
                        tar_file.extract(member=member, path=extract_dir_path)
                return True

            elif re.match(gzip_pattern, item):
                self._create_folder_for_archive_unpacking(extract_dir_path)
                with gzip.open(join(path, item), 'rb') as gzip_file:
                    with open(join(extract_dir_path, item.rsplit('.gz', 1)[0]), 'wb') as f_out:
                        shutil.copyfileobj(gzip_file, f_out)
                return True

            elif re.match(xz_pattern, item):
                self._create_folder_for_archive_unpacking(extract_dir_path)
                with lzma.open(join(path, item), 'rb') as xz_file:
                    with open(join(extract_dir_path, item.rsplit('.xz', 1)[0]), 'wb') as f_out:
                        shutil.copyfileobj(xz_file, f_out)
                return True

        except (BadZipfile, TarError, OSError, LZMAError, EOFError, zlib_error):
            log_warning("Cannot unpack {0} file - seems like it is corrupted!".format(join(path, item)))

        return False

    @staticmethod
    def _create_folder_for_archive_unpacking(snap_extract_dir):
        if not os.path.isdir(snap_extract_dir):
            os.mkdir(snap_extract_dir)

    @staticmethod
    def _verify_if_sw_version_is_knife(sw_version):
        pattern = r'^SBTS[0-9A-R]{0,4}_ENB_[0-9]{4}_[0-9]{6}_[0-9]{7}T?[1-2]?$'
        return bool(re.match(pattern, sw_version))

    @log_input_and_output
    def _extend_snapshot_documentation_csv(self, additional_documentation_path):
        csv_file_name = "{}_trbl_log_list.csv".format(self._sw_version.split("T1")[0])
        csv_file_path = join(self._snapshot_documentation_path, csv_file_name)

        with open(additional_documentation_path, "r") as r, open(csv_file_path, "a") as w:
            reader = csv.DictReader(r, delimiter=";")

            writer = csv.DictWriter(w, fieldnames=reader.fieldnames, delimiter=";")
            writer.writerows(list(reader))

    def _applay_filters(self, items: str, ru_name: str, item_type='filenames'):
        """
        Applies filters to mandatory container or files based on item type.
        The order in which filters are applied is important.

        :param item_type: type of items to be filtered, can be 'container' or 'filenames'
        :type item_type: str
        :param items: mandatory containers or filenames to be filtered
        :type items: str | list[str]
        :return: filtered items
        :rtype: str | list[str]
        """
        if not isinstance(items, list):
            items = [items]

        filters = [
            partial(self._filter_files_by_rmod_program, ru_name),
        ]

        for file_filter in filters:
            items = file_filter(items)

        return items[0] if item_type == 'container' else items

    def _find_parent_archive(self, filtered_snap_file_list: dict, search_pattern: str) -> Optional[ZipInfo]:
        """
        Find parent archive name if exists for file container from filtered and parsed snapshot_file_list_txt.
        File container can be stored also at higher depth of snapshot archive. In that case parent archive is equal to file container.

        :param filtered_snap_file_list: Filtered and parsed to dictionary snapshot_file_list.txt.
        :type filtered_snap_file_list: dict
        :param search_pattern: Pattern to search for the parent archive.
        :type search_pattern: str
        :return: Archive where the file container is stored, or None if not found, e.g. archive BTS_part1.zip
        :rtype: ZipInfo | SimpleNamespace | None
        """
        with ZipFile(self._snapshot_path, 'r') as z:
            for archive, content in filtered_snap_file_list.items():
                if re.search(search_pattern, archive):
                    return SimpleNamespace(filename=archive)
                if any(re.search(search_pattern, f) for f in content):
                    return next((f for f in z.infolist() if f.filename == archive), None)

    def _find_container_in_archive(self, parent_archive: Union[str, ZipInfo], container_search_pattern: str) -> Optional[ArchiveObj]:
        """
        Find mandatory file container in the snapshot parent archive.

        :param parent_archive: Parent archive where the file container is stored. If parent archive arg is str,
                               it means that file container is stored at the root of snapshot archive.
        :type parent_archive: ZipInfo
        :param container_search_pattern: Pattern to search for the mandatory file container.
        :type container_search_pattern: str
        :return: ArchiveObj | None
        """
        with ZipFile(self._snapshot_path, 'r') as z:
            if isinstance(parent_archive, ZipInfo):
                with z.open(parent_archive) as snap_arch:
                    for archive_obj in self._list_archive(snap_arch):
                        if re.search(container_search_pattern, archive_obj.name):
                            return archive_obj

            else:
                matched = next((f for f in z.infolist() if re.search(container_search_pattern, f.filename)), None)
                return ArchiveObj(matched.filename, z.read(matched)) if matched else None

    def _find_missing_files_in_container(self, container_archive: ArchiveObj, mandatory_filenames: list[str], rmod_index: str,
                                         rmod_serial_number: str, prefix: str = "") -> list[str]:
        """
        Searches for mandatory files in the container archive and returns a list of missing files.

        :param container_archive: ArchiveObj representing the mandatory file container
        :type container_archive: ArchiveObj
        :param mandatory_filenames: list of mandatory filenames to search for
        :type mandatory_filenames: list[str]
        :param rmod_index: index of the RMOD e.g. "1"
        :type rmod_index: str
        :param rmod_serial_number: serial number of the RMOD e.g. "1234567"
        :type rmod_serial_number: str
        :param prefix: prefix to be used to create exact matched path
        :type prefix: str
        :return: list of mandatory files that have not been found in the container archive
        """
        missing = []
        for file_name in mandatory_filenames:
            pattern = self._create_mandatory_file_search_pattern(file_name, rmod_index, rmod_serial_number)
            if not self._search_in_archive(container_archive, pattern, prefix):
                missing.append(file_name)
                continue
            log_result(f"mandatory file '{file_name}' matched with {self._matched_path}")
        return missing

    def _create_file_container_search_pattern(self, searched_container: str, rmod_index: str, rmod_serial_number: str) -> str:
        """
        Creates a regex pattern to search for the mandatory file container in the BTS snapshot sub files.

        :param searched_container: File container name to search for e.g. "__NODE_ID__messages-pm2.tar.gz"
        :type searched_container: str
        :param rmod_index: Index of the RMOD e.g. "1"
        :type rmod_index: str
        :param rmod_serial_number: Serial number of the RMOD e.g. "1234567"
        :type rmod_serial_number: str
        :return: Regex pattern to match the file container name
        :rtype: str
        """
        if "__NODE_ID__" in searched_container:
            searched_container = searched_container.replace("__NODE_ID__", r"\d+_")

        pattern = (rf"(?=.*{re.escape(rmod_serial_number)})(?=.*RMOD_L_{rmod_index}_{searched_container}$)"
                   rf"|^{searched_container}$")

        return pattern

    def _create_mandatory_file_search_pattern(self, mandatory_file: str, rmod_index: str, rmod_serial_number: str) -> str:
        """
        Creates a regex pattern to search for mandatory files in the container archive.

        :param mandatory_file: Name of the mandatory file to search for e.g. "dmesg.txt"
        :type mandatory_file: str
        :param rmod_index: Index of the RMOD e.g. "1"
        :type rmod_index: str
        :param rmod_serial_number: Serial number of the RMOD e.g. "1234567"
        :type rmod_serial_number: str
        :return: Regex pattern to match the mandatory file name
        :rtype: str
        """
        if '__NODE_ID__' in mandatory_file:
            mandatory_file = mandatory_file.replace("__NODE_ID__", r"\d+_")

        if '#' in mandatory_file:
            mandatory_file = mandatory_file.replace("#", r"\d")

        if re.search(r'(?<![.\])])\*', mandatory_file):  # Check if '*' regex is properly implemented and add '.' before it if not
            mandatory_file = re.sub(r'(?<![.\])])\*', r'.*', mandatory_file)

        pattern = (rf"((?=.*{rmod_serial_number})(?=.*RMOD_L_{rmod_index}_{mandatory_file}$))"
                   rf"|^{mandatory_file}$")

        return pattern

    def _list_archive(self, archive: Union[ZipExtFile, ArchiveObj]) -> list[ArchiveObj]:
        """
        Returns a list of files present in an archive, limited to one level of depth.

        :param archive: Archive file to list
        :type archive: ZipExtFile | ArchiveObj
        :return: List of ArchiveObj objects for each file in the archive
        :rtype: list[ArchiveObj]
        """
        if isinstance(archive, ZipExtFile):
            archive = ArchiveObj(archive.name, archive.read())

        archive.data.seek(0)
        if archive.name.endswith('.zip'):
            with ZipFile(archive.data) as f_zip:
                return [ArchiveObj(name, f_zip.read(name)) for name in f_zip.namelist()]
        elif archive.name.endswith(('.tar', '.tar.gz', '.tgz', '.txz')):
            with TarFile.open(fileobj=archive.data, mode='r:*') as f_tar:
                return [ArchiveObj(m.name, f_tar.extractfile(m).read()) for m in f_tar.getmembers()]
        elif archive.name.endswith('.gz'):
            with gzip.open(archive.data) as gf:
                decompressed = gf.read()
            return [ArchiveObj(archive.name.removesuffix('.gz'), decompressed)]
        elif archive.name.endswith('.xz'):
            decompressed = lzma.decompress(archive.data.read())
            return [ArchiveObj(archive.name.removesuffix('.xz'), decompressed)]
        else:
            log_warning(f"Unsupported archive extension: {archive.name}")

        return []

    def _is_archive(self, name: str) -> bool:
        return name.endswith(ARCHIVE_EXTENSIONS)

    def _search_in_archive(self, archive: ArchiveObj, search_pattern: str, prefix: str = "", visited=None) -> bool:
        current_path = archive.name if not prefix else f"{prefix}/{archive.name}"
        if re.search(search_pattern, archive.name):
            self._matched_path = current_path
            return True
        if visited is None:
            visited = set()
        if current_path in visited:
            return False
        visited.add(current_path)

        sig = archive.data.read(2)
        archive.data.seek(0)

        try:
            if archive.name.endswith(".zip") or sig == b'PK':
                return self._search_in_zip(archive.data, search_pattern, f"{current_path}", visited)

            elif archive.name.endswith((".tar", ".tar.gz", ".tgz", ".txz")):
                return self._search_in_tar(archive.data, search_pattern, f"{current_path}", visited)

            elif archive.name.endswith(".gz"):
                return self._search_in_gz(archive.data, search_pattern, f"{current_path}", visited)

            elif archive.name.endswith(".xz"):
                return self._search_in_xz(archive.data, search_pattern, f"{current_path}", visited)

        except Exception as e:
            log_warning(f"Error processing archive '{archive.name}', error: {e}")

        return False

    def _search_in_zip(self, data: io.BytesIO, search_pattern: str, prefix: str, visited: set) -> bool:
        with ZipFile(data) as zf:
            for file_name in zf.namelist():
                if re.search(search_pattern, file_name):
                    self._matched_path = f'{prefix}/{file_name}'
                    return True
                if self._is_archive(file_name):
                    with zf.open(file_name) as f:
                        inner_archive = ArchiveObj(file_name, f.read())
                        if self._search_in_archive(inner_archive, search_pattern, prefix, visited):
                            return True
        return False

    def _search_in_tar(self, data: io.BytesIO, search_pattern: str, prefix: str, visited: set) -> bool:
        with TarFile.open(fileobj=data, mode='r:*') as tf:
            for member in tf.getmembers():
                _member_name = member.name.split('/')[-1] if member.isfile() else member.name
                if re.search(search_pattern, _member_name):
                    self._matched_path = f'{prefix}/{member.name}'
                    return True
                if self._is_archive(member.name):
                    f = tf.extractfile(member)
                    if f:
                        inner_archive = ArchiveObj(member.name, f.read())
                        if self._search_in_archive(inner_archive, search_pattern, prefix, visited):
                            return True
        return False

    def _search_in_gz(self, data: io.BytesIO, search_pattern: str, prefix: str, visited: set) -> bool:
        with gzip.open(data) as gf:
            file_name = prefix.split('/')[-1].removesuffix('.gz')
            if re.search(search_pattern, file_name):
                self._matched_path = f'{prefix}/{file_name}'
                return True
            if self._is_archive(file_name):
                decompressed = gf.read()
                inner_archive = ArchiveObj(file_name, decompressed)
                if self._search_in_archive(inner_archive, search_pattern, prefix, visited):
                    return True

        return False

    def _search_in_xz(self, data: io.BytesIO, search_pattern: str, prefix: str, visited: set) -> bool:
        file_name = prefix.split('/')[-1].removesuffix(".xz")
        if re.search(search_pattern, file_name):
            self._matched_path = f'{prefix}/{file_name}'
            return True
        if self._is_archive(file_name):
            decompressed = lzma.decompress(data.read())
            inner_archive = ArchiveObj(file_name, decompressed)
            if self._search_in_archive(inner_archive, search_pattern, prefix, visited):
                return True

        return False

    def _create_missing_files_err_msg(self) -> list:
        missing_msg = [f"RMOD name: {rmod['ru_name']}, sn: {rmod['ru_serial_number']}, scm_flag: {rmod['ru_scm_flag']}\n"
                       + '\n'.join(rmod['missing_files'])
                       for rmod in self._missing_files]
        return missing_msg

    def _find_matched_paths(self, subarchives: dict, patterns: dict) -> tuple[list[str], list[str]]:
        """
        Finds matched paths for given patterns in the snapshot subarchives.

        :param subarchives: Dictionary of subarchives to search in
        :type subarchives: dict
        :param patterns: Dictionary of file names and theirs patterns to search for e.g. {"dmesg.txt": r"^dmesg.txt$"}
        :type patterns: dict
        :return: List of matched paths and list of file names that were not found e.g. ['path/to/dmesg.txt'], ['auth.log']
        :rtype: tuple[list[str], list[str]]
        """
        matched_paths = []

        with ZipFile(self._snapshot_path, "r") as z:
            for rmod_archive in subarchives.keys():
                matched_archive = next((f for f in z.infolist() if f.filename == rmod_archive), None)
                if not matched_archive:
                    continue

                target = ArchiveObj(matched_archive.filename, z.read(matched_archive))
                for m_file, pattern in list(patterns.items()):
                    if self._search_in_archive(target, pattern):
                        matched_paths.append(self._matched_path)
                        patterns.pop(m_file, None)
                if not patterns:
                    break

        return matched_paths, list(patterns.keys())
